const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uuid=()=>crypto.randomUUID?.()||Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,'0')).join('');
let freeMode=false,chestPage=0,chestSelected=null;
let blocks=[],textures=new Map(),source=null,sourceURL='',project=null,view='3d',viewer=null,worker=null,job=0,custom=new Set(),done=new Set(),collected=new Set(),history=[],future=[],row=0,db=null,saveTimer,toastTimer,dirty=false;
const ids=['width','height','aspect','fit','position','palettePreset','method','dither','brightness','contrast','saturation','maxColors','transparent','smooth','nearest'];
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4500)}
const safe=fn=>async(...args)=>{try{await fn(...args)}catch(e){console.error(e);toast(e.message||'Please try again.')}};
function modal(title,html){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;if(!$('modal').open)$('modal').showModal()}
$('closeModal').onclick=()=>$('modal').close();$('modal').onclick=e=>{if(e.target===$('modal'))$('modal').close()};
async function initDB(){db=await new Promise((resolve,reject)=>{const r=indexedDB.open('blockloom',1);r.onupgradeneeded=()=>r.result.createObjectStore('projects',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function dbRun(mode,fn){return new Promise((resolve,reject)=>{if(!db)return reject(Error('Browser storage unavailable. Export a project backup instead.'));const tx=db.transaction('projects',mode),r=fn(tx.objectStore('projects'));tx.oncomplete=()=>resolve(r.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
function snapshot(){return {...project,name:$('projectName').value.trim()||'Untitled build',done:[...done],collected:[...collected],updated:Date.now()}}
async function persist(announce=false){if(!project)return;const p=snapshot();p.thumbnail=colorCanvas(p,2).toDataURL('image/png');await dbRun('readwrite',s=>s.put(p));project.name=p.name;project.updated=p.updated;$('settingsStatus').textContent=dirty?'Settings changed · generate to apply':'Saved on this device';if(announce)toast('Project saved on this device.')}
function autosave(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>persist().catch(e=>{$('settingsStatus').textContent='Not saved · export a backup';toast(e.message)}),500)}
function settings(){const s={};for(const id of ids){const el=$(id);s[id]=el.type==='checkbox'?el.checked:el.value}for(const k of ['brightness','contrast','saturation','dither','width','height','maxColors'])s[k]=+s[k];s.custom=[...custom];return s}
function palette(){const p=$('palettePreset').value;return blocks.filter(b=>p==='all'||(p==='custom'?custom.has(b.id):p==='both'?['Concrete','Wool'].includes(b.category):p==='survival'?b.survival:b.category===p))}
function updatePalette(){const p=palette();$('paletteCount').textContent=p.length+' blocks';$('paletteStrip').innerHTML=p.slice(0,32).map(b=>`<span title="${esc(b.name)}" style="background:rgb(${b.color})"></span>`).join('')}
function updateOutputs(){for(const id of ['dither','brightness','contrast','saturation'])$(id+'Value').textContent=id==='dither'?Math.round($(id).value*100)+'%':$(id).value}
function markDirty(){dirty=true;$('settingsStatus').textContent='Settings changed · generate to apply';updatePalette();updateOutputs()}
function dimensionChanged(which){let w=Math.max(1,Math.min(256,Math.round(+$('width').value)||64)),h=Math.max(1,Math.min(256,Math.round(+$('height').value)||64));if($('aspect').checked&&source){if(which==='height'){w=Math.max(1,Math.round(h*source.width/source.height));if(w>256){w=256;h=Math.max(1,Math.round(w*source.height/source.width))}}else{h=Math.max(1,Math.round(w*source.height/source.width));if(h>256){h=256;w=Math.max(1,Math.round(h*source.width/source.height))}}}$('width').value=w;$('height').value=h;document.querySelectorAll('[data-width]').forEach(b=>b.classList.toggle('selected',+b.dataset.width===w));markDirty()}
for(const id of ids)$(id).onchange=()=>['width','height','aspect'].includes(id)?dimensionChanged(id):markDirty();for(const id of ['dither','brightness','contrast','saturation'])$(id).oninput=markDirty;
$('presets').onclick=e=>{if(e.target.dataset.width){$('width').value=e.target.dataset.width;dimensionChanged('width')}};
function loadImage(url){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Unable to read this image. Try PNG, JPEG or WebP.'));img.src=url})}
async function useImage(file){if(!file.type.startsWith('image/'))throw Error('Choose an image file.');if(file.size>30*1024*1024)throw Error('Choose an image smaller than 30 MB.');if(project&&db)await persist();const url=URL.createObjectURL(file);try{const img=await loadImage(url),scale=Math.min(1,1600/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);sourceURL=c.toDataURL('image/png');source=await loadImage(sourceURL);$('sourceName').setAttribute('data-no-i18n','');$('sourceName').textContent=file.name;$('projectName').value=file.name.replace(/\.[^.]+$/,'').slice(0,100);project=null;done.clear();collected.clear();dimensionChanged('width');await generate()}finally{URL.revokeObjectURL(url)}}
$('imageInput').onchange=safe(async e=>{if(e.target.files[0])await useImage(e.target.files[0]);e.target.value=''});for(const ev of ['dragover','dragenter'])$('dropzone').addEventListener(ev,e=>{e.preventDefault();$('dropzone').classList.add('drag')});for(const ev of ['dragleave','drop'])$('dropzone').addEventListener(ev,e=>{e.preventDefault();$('dropzone').classList.remove('drag')});$('dropzone').addEventListener('drop',safe(async e=>{if(e.dataTransfer.files[0])await useImage(e.dataTransfer.files[0])}));
function sampleImage(){const c=document.createElement('canvas');c.width=800;c.height=600;const x=c.getContext('2d');let g=x.createLinearGradient(0,0,0,600);g.addColorStop(0,'#172e43');g.addColorStop(.5,'#d28f72');g.addColorStop(1,'#183d43');x.fillStyle=g;x.fillRect(0,0,800,600);x.fillStyle='#f0bd79';x.beginPath();x.arc(580,180,70,0,Math.PI*2);x.fill();const poly=(p,color)=>{x.fillStyle=color;x.beginPath();p.forEach(([a,b],i)=>i?x.lineTo(a,b):x.moveTo(a,b));x.closePath();x.fill()};poly([[0,325],[190,115],[350,330],[500,185],[800,360],[800,600],[0,600]],'#667e86');poly([[80,235],[190,115],[290,238],[213,200],[184,223],[160,198]],'#d2d6c4');poly([[0,400],[170,267],[335,420],[490,280],[650,385],[800,265],[800,600],[0,600]],'#314f59');poly([[0,450],[180,380],[310,438],[510,392],[800,440],[800,600],[0,600]],'#18383b');x.fillStyle='#417d80';x.fillRect(0,452,800,148);poly([[290,455],[580,460],[720,600],[155,600]],'#759b92');let seed=32;const rnd=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};for(let i=0;i<90;i++){x.fillStyle=i%3===0?'#aab39b':'#527f7b';x.fillRect(rnd()*800,465+rnd()*135,15+rnd()*80,2+rnd()*3)}const tree=(a,b,s)=>{x.fillStyle='#27372f';x.fillRect(a-s*.06,b-s,s*.12,s);poly([[a,b-s*1.9],[a-s*.46,b-s*.55],[a+s*.46,b-s*.55]],'#183a36');poly([[a,b-s*1.5],[a-s*.58,b-s*.1],[a+s*.58,b-s*.1]],'#1e433a')};for(let i=0;i<15;i++)tree(i*23,460,30+rnd()*35);for(let i=0;i<8;i++)tree(650+i*25,450,55+rnd()*35);poly([[0,550],[95,510],[200,550],[270,600],[0,600]],'#243e35');tree(58,570,110);tree(142,572,75);x.fillStyle='#b37242';x.fillRect(460,406,74,47);poly([[448,410],[497,371],[547,410]],'#402b2b');x.fillStyle='#f0bd69';x.fillRect(473,421,14,13);x.fillRect(510,420,13,16);x.fillStyle='#533b2a';x.fillRect(493,426,11,27);return c.toDataURL('image/png')}
async function demo(){if(project&&db)await persist();sourceURL=sampleImage();source=await loadImage(sourceURL);$('sourceName').removeAttribute('data-no-i18n');$('sourceName').textContent='Sample · Alpine escape';$('projectName').value='Alpine escape';$('width').value=96;$('height').value=72;$('palettePreset').value='all';project=null;done.clear();collected.clear();await generate()}
$('demoBtn').onclick=safe(demo);
function sampled(s){const c=document.createElement('canvas');c.width=s.width;c.height=s.height;const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=!s.nearest;ctx.imageSmoothingQuality='high';let dw=c.width,dh=c.height,dx=0,dy=0;if(s.fit!=='stretch'){const r=s.fit==='cover'?Math.max(c.width/source.width,c.height/source.height):Math.min(c.width/source.width,c.height/source.height);dw=source.width*r;dh=source.height*r;const f=s.position==='top'?0:s.position==='bottom'?1:.5;dx=(c.width-dw)*f;dy=(c.height-dh)*f}ctx.drawImage(source,dx,dy,dw,dh);return ctx.getImageData(0,0,c.width,c.height).data}
async function generate(){if(!source)throw Error('Upload an image first.');dimensionChanged('width');const s=settings(),p=palette();if(!p.length)throw Error('Select at least one block.');const token=++job;if(worker)worker.terminate();$('loading').hidden=false;$('convertBtn').disabled=true;const prev=project;try{const cells=await new Promise((resolve,reject)=>{worker=new Worker('./worker.js',{type:'module'});worker.onmessage=e=>e.data.error?reject(Error(e.data.error)):resolve(e.data.cells);worker.onerror=()=>reject(Error('Conversion failed. Try a smaller build.'));worker.postMessage({pixels:sampled(s),width:s.width,height:s.height,palette:p,settings:s})});if(token!==job)return;project={format:'blockloom',version:1,id:prev?.id||uuid(),name:$('projectName').value||'Untitled build',width:s.width,height:s.height,palette:p,cells,source:sourceURL,settings:s,created:prev?.created||Date.now()};done.clear();collected.clear();history=[];future=[];row=0;dirty=false;refresh(true);autosave();$('settingsStatus').textContent='Build generated · progress reset'}finally{if(token===job){$('loading').hidden=true;$('convertBtn').disabled=false}}}
$('convertBtn').onclick=safe(generate);
function colorCanvas(p,scale=1,textured=false){const c=document.createElement('canvas');c.width=p.width*scale;c.height=p.height*scale;const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;p.cells.forEach((b,i)=>{if(b<0)return;const x=i%p.width*scale,y=Math.floor(i/p.width)*scale,t=textures.get(p.palette[b].texture);if(textured&&t)ctx.drawImage(t,x,y,scale,scale);else{ctx.fillStyle='rgb('+p.palette[b].color+')';ctx.fillRect(x,y,scale,scale)}});return c}
function renderPreview(rebuild=false){if(!project)return;$('threeHost').hidden=view!=='3d';$('canvasHost').hidden=view==='3d';$('frontBtn').hidden=view!=='3d';$('cameraMode').hidden=view!=='3d';$('viewHint').textContent=view==='3d'?(freeMode?'Click view · WASD move · Q/E down/up · Drag to look · Shift faster · Esc exit':'Drag to rotate · Scroll to zoom'):view==='compare'?'Original image (left) · Converted blocks (right)':'Scroll to zoom · Drag to pan · Reset view to fit';if(view==='3d'){try{if(!viewer){viewer=new BuildViewer($('threeHost'),inspect);viewer.setFree(freeMode)}if(rebuild||viewer.p!==project)viewer.setProject(project);viewer.resize()}catch(e){$('threeHost').replaceChildren();viewer=new SoftwareViewer($('threeHost'),inspect,textures);viewer.setProject(project);viewer.setFree(freeMode)}return}const c=$('previewCanvas'),ctx=c.getContext('2d'),pix=colorCanvas(project,view==='texture'?16:4,view==='texture');if(view==='original'){c.width=source.width;c.height=source.height;ctx.drawImage(source,0,0)}else if(view==='compare'){c.width=project.width*8+16;c.height=project.height*4;ctx.fillStyle='#101927';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(source,0,0,project.width*4,c.height);ctx.drawImage(pix,project.width*4+16,0)}else{c.width=pix.width;c.height=pix.height;ctx.drawImage(pix,0,0)}}
function setView(v){view=v;resetTextureView();document.querySelectorAll('[data-view]').forEach(b=>{const on=b.dataset.view===v;b.classList.toggle('active',on);b.setAttribute('aria-selected',on)});renderPreview()}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('resetViewBtn').onclick=()=>{if(view==='3d')viewer?.reset();else resetTextureView()};$('frontBtn').onclick=()=>viewer?.front();$('cameraMode').onclick=()=>{freeMode=!freeMode;viewer?.setFree(freeMode);$('cameraMode').textContent=freeMode?'Exit free camera':'Free camera';$('cameraMode').setAttribute('aria-pressed',freeMode);renderPreview()};
const stateText=b=>Object.entries(b.properties||{}).map(([k,v])=>k+'='+v).join(', ');
function inspect(i){if(!project||i<0||i>=project.cells.length)return;const b=project.cells[i],pos=blockPosition(i,project.width,project.height),state=b<0?'':stateText(project.palette[b]),text=`${b<0?'Air':project.palette[b].name}${state?' ['+state+']':''} · X ${pos.x}, Y ${pos.y}, Z 0`;$('selectedBlock').textContent=text;$('blueprintInfo').textContent=text;return b}
function renderStats(){const counts=countsFor(project.cells),n=[...counts.values()].reduce((a,b)=>a+b,0);$('statDimensions').textContent=project.width+' × '+project.height;$('statTotal').textContent=n.toLocaleString();$('statTypes').textContent=counts.size;$('statStacks').textContent=[...counts.values()].reduce((a,b)=>a+Math.ceil(b/64),0).toLocaleString();$('materialBadge').textContent=counts.size;$('previewSub').textContent=`${project.width} × ${project.height} blocks · ${n.toLocaleString()} blocks`}
function renderMaterials(){const q=$('materialSearch').value.toLowerCase(),list=[...countsFor(project.cells)].filter(([i])=>blockSearchText(project.palette[i]).includes(q));list.sort($('sort').value==='name'?((a,b)=>t(project.palette[a[0]].name).localeCompare(t(project.palette[b[0]].name),getLanguage())):((a,b)=>b[1]-a[1]));$('materialsBody').innerHTML=list.map(([i,n])=>{const b=project.palette[i];return `<tr><td><input type="checkbox" data-collect="${i}" aria-label="Collected ${esc(b.name)}" ${collected.has(b.id)?'checked':''}></td><td><div class="block-cell"><span class="num">${i+1}</span><img src="${b.texture}" alt=""><div>${esc(b.name)}${stateText(b)?'<small>'+esc(stateText(b))+'</small>':''}</div></div></td><td>${n.toLocaleString()}</td><td title="${Math.floor(n/1728)} full shulker boxes">${Math.floor(n/64)} stacks + ${n%64}</td></tr>`}).join('')||'<tr><td colspan="4">No matching materials.</td></tr>';const all=[...countsFor(project.cells).keys()];$('collectionSummary').textContent=`${all.filter(i=>collected.has(project.palette[i].id)).length} of ${all.length} materials collected`;renderChest(list)}
$('materialsBody').onchange=e=>{const i=+e.target.dataset.collect;if(!Number.isInteger(i))return;const id=project.palette[i].id;e.target.checked?collected.add(id):collected.delete(id);renderMaterials();autosave()};$('materialSearch').oninput=()=>{chestPage=0;project&&renderMaterials()};$('sort').onchange=()=>{chestPage=0;project&&renderMaterials()};
function renderBlueprint(){if(!project)return;const max=Math.min(40,Math.floor(4096/Math.max(project.width,project.height)));$('zoom').max=max;if(+$('zoom').value>max)$('zoom').value=max;const s=+$('zoom').value,c=$('blueprint');c.width=project.width*s;c.height=project.height*s;const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.drawImage(colorCanvas(project,s,true),0,0);for(const i of done){const x=i%project.width*s,y=Math.floor(i/project.width)*s;ctx.fillStyle='#52cf9780';ctx.fillRect(x,y,s,s);if(s>=12){ctx.fillStyle='#fff';ctx.font=`${s*.75}px sans-serif`;ctx.fillText('✓',x+1,y+s*.8)}}if($('grid').checked&&s>=6){ctx.strokeStyle='#0005';ctx.lineWidth=.5;ctx.beginPath();for(let x=0;x<=c.width;x+=s){ctx.moveTo(x,0);ctx.lineTo(x,c.height)}for(let y=0;y<=c.height;y+=s){ctx.moveTo(0,y);ctx.lineTo(c.width,y)}ctx.stroke()}if($('labels').checked&&s>=18){ctx.font=`${Math.min(12,s*.36)}px monospace`;ctx.textAlign='center';ctx.textBaseline='middle';project.cells.forEach((b,i)=>{if(b<0)return;const x=i%project.width*s+s/2,y=Math.floor(i/project.width)*s+s/2;ctx.fillStyle='#0009';ctx.fillRect(x-s*.43,y-s*.25,s*.86,s*.5);ctx.fillStyle='white';ctx.fillText(b+1,x,y)})}}
function cellAt(e){const r=$('blueprint').getBoundingClientRect(),s=+$('zoom').value;return Math.floor((e.clientY-r.top)/s)*project.width+Math.floor((e.clientX-r.left)/s)}
function remember(){history.push({cells:project.cells.slice(),done:[...done]});if(history.length>40)history.shift();future=[]}
function edited(){collected.clear();refresh(true);autosave()}
function indexFor(id){let i=project.palette.findIndex(b=>b.id===id);if(i<0){i=project.palette.length;project.palette.push(blocks.find(b=>b.id===id))}return i}
$('blueprint').onmousemove=e=>inspect(cellAt(e));$('blueprint').onclick=e=>{const i=cellAt(e);if(i<0||i>=project.cells.length)return;const tool=$('editorTool').value,b=inspect(i);if(tool==='pick'){if(b>=0){$('paintBlock').value=project.palette[b].id;$('editorTool').value='paint'}return}if(tool==='complete'){if(b<0)return;done.has(i)?done.delete(i):done.add(i);renderBlueprint();renderGuide();autosave()}else if(tool==='paint'||tool==='erase'){remember();project.cells[i]=tool==='erase'?-1:indexFor($('paintBlock').value);done.delete(i);edited();inspect(i)}};
for(const id of ['zoom','grid','labels'])$(id).oninput=renderBlueprint;
function travel(from,to){if(!project||!from.length)return;to.push({cells:project.cells.slice(),done:[...done]});const s=from.pop();project.cells=s.cells;done=new Set(s.done);edited()}
$('undoBtn').onclick=()=>travel(history,future);$('redoBtn').onclick=()=>travel(future,history);document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?travel(future,history):travel(history,future)}});
$('replaceBtn').onclick=()=>{if(!project)return;modal('Replace a material',`<p>Replace every instance in this build. This change can be undone.</p><div class="two" style="margin-top:20px"><label>Replace<select id="replaceFrom">${[...countsFor(project.cells).keys()].map(i=>`<option value="${i}">${esc(project.palette[i].name)}</option>`).join('')}</select></label><label>With<select id="replaceTo">${blocks.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></label></div><div class="dialog-actions"><button class="primary" id="doReplace">Replace all blocks</button></div>`);$('doReplace').onclick=()=>{if(!$('replaceFrom').value)return;remember();const from=+$('replaceFrom').value,to=indexFor($('replaceTo').value);project.cells=project.cells.map((v,i)=>{if(v===from){done.delete(i);return to}return v});$('modal').close();edited()}};
function renderGuide(){if(!project)return;row=Math.max(0,Math.min(project.height-1,row));const total=project.cells.filter(v=>v>=0).length,pc=total?Math.round(done.size/total*100):100;$('progressText').textContent=`${pc}% complete · ${done.size.toLocaleString()} / ${total.toLocaleString()} blocks`;$('progressBar').style.width=pc+'%';$('rowNumber').value=row+1;$('rowNumber').max=project.height;$('rowTotal').textContent='/ '+project.height;$('prevRow').disabled=row===0;$('nextRow').disabled=row===project.height-1;const start=(project.height-1-row)*project.width;let complete=true;for(let x=0;x<project.width;x++)if(project.cells[start+x]>=0&&!done.has(start+x))complete=false;$('completeRow').textContent=complete?'Unmark row':'Mark row placed';const c=$('rowCanvas'),scale=8;c.width=project.width*scale;c.height=project.height*scale;const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.drawImage(colorCanvas(project,scale,true),0,0);const y=(project.height-row-1)*scale;ctx.fillStyle='#0006';ctx.fillRect(0,0,c.width,y);ctx.fillRect(0,y+scale,c.width,c.height-y-scale);ctx.strokeStyle='#f9d269';ctx.lineWidth=2;ctx.strokeRect(1,y+1,c.width-2,scale-2);let html='',step=0;for(const run of rowRuns(project.cells,project.width,project.height,row)){const a=run.start,z=run.end,b=run.block<0?null:project.palette[run.block];step++;html+=`<div role="listitem" class="run ordered-run ${Array.from({length:z-a+1},(_,k)=>start+a+k).every(i=>project.cells[i]<0||done.has(i))?'placed':''}">${b?`<img src="${b.texture}" alt="">`:'□'}<div><span class="step-number">Step ${step}</span><b>${b?`Place ${z-a+1} × ${esc(b.name)}`:`Leave ${z-a+1} empty space${z>a?'s':''}`}</b><strong class="run-count">${z-a+1}<small>block${z-a+1===1?'':'s'}</small></strong><small>${a===z?`At X ${a}`:`From X ${a} to X ${z}`} · Y ${row}${b&&stateText(b)?' · '+esc(stateText(b)):''}</small></div></div>`}$('rowSequence').innerHTML=html;$('rowHeading').textContent=`Row ${row+1} of ${project.height} · Y = ${row}`;$('rowStrip').innerHTML=Array.from({length:project.width},(_,x)=>{const i=start+x,b=project.cells[i];return `<button class="row-cell ${done.has(i)?'placed':''}" data-place="${i}" title="X ${x}: ${b<0?'Air':esc(project.palette[b].name)}" aria-label="${b<0?'Air':esc(project.palette[b].name)} at X ${x}${done.has(i)?', placed':''}">${b<0?'<span>—</span>':`<img src="${project.palette[b].texture}" alt="">`}<small>${x}</small></button>`}).join('')}
$('rowStrip').onclick=e=>{const el=e.target.closest('[data-place]');if(!el)return;const i=+el.dataset.place;if(project.cells[i]<0)return;done.has(i)?done.delete(i):done.add(i);renderGuide();renderBlueprint();autosave()};
$('prevRow').onclick=()=>{row--;renderGuide()};$('nextRow').onclick=()=>{row++;renderGuide()};$('rowNumber').onchange=()=>{row=Math.floor(+$('rowNumber').value||1)-1;renderGuide()};$('completeRow').onclick=()=>{const start=(project.height-1-row)*project.width,list=Array.from({length:project.width},(_,x)=>start+x).filter(i=>project.cells[i]>=0),all=list.every(i=>done.has(i));list.forEach(i=>all?done.delete(i):done.add(i));renderGuide();renderBlueprint();autosave()};
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tool]').forEach(t=>t.classList.toggle('active',t===b));for(const name of ['materials','blueprint','guide'])$(name+'Panel').hidden=name!==b.dataset.tool;const preview=b.dataset.tool==='preview';document.querySelector('.preview').hidden=!preview;document.querySelector('.stats').hidden=!preview;document.querySelector('.tools').hidden=preview;if(preview){renderPreview();viewer?.resize()}if(b.dataset.tool==='blueprint'){fitBlueprint();}if(b.dataset.tool==='guide')renderGuide()});
function refresh(rebuild=false){renderStats();renderMaterials();renderPreview(rebuild);renderBlueprint();renderGuide();$('undoBtn').disabled=!history.length;$('redoBtn').disabled=!future.length}
$('paletteBtn').onclick=()=>{let selected=new Set(palette().map(b=>b.id));modal('Choose your building blocks',`<p>162 texture-sampled blocks from Java 1.20.4.</p><div class="actions" style="margin-top:16px"><input id="paletteSearch" placeholder="Search blocks" style="width:100%"><button id="selectAll">All</button><button id="selectNone">None</button></div><div class="palette-grid" id="paletteGrid"></div><div class="dialog-actions"><small id="chosenCount"></small><button class="primary" id="applyPalette">Use selected blocks</button></div>`);const render=()=>{const q=$('paletteSearch').value.toLowerCase();$('paletteGrid').innerHTML=blocks.filter(b=>blockSearchText(b).includes(q)).map(b=>`<label class="palette-item" title="${esc(b.notes||b.category)}"><input type="checkbox" value="${b.id}" ${selected.has(b.id)?'checked':''}><img src="${b.texture}" alt=""><span>${esc(b.name)}</span></label>`).join('');$('chosenCount').textContent=selected.size+' selected'};$('paletteSearch').oninput=render;$('paletteGrid').onchange=e=>{e.target.checked?selected.add(e.target.value):selected.delete(e.target.value);$('chosenCount').textContent=selected.size+' selected'};$('selectAll').onclick=()=>{selected=new Set(blocks.map(b=>b.id));render()};$('selectNone').onclick=()=>{selected.clear();render()};$('applyPalette').onclick=()=>{if(!selected.size)return toast('Select at least one block.');custom=selected;$('palettePreset').value='custom';markDirty();$('modal').close()};render()};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
const filename=()=>(project.name||'build').replace(/[^\p{L}\p{N}_-]/gu,'-').slice(0,80);
function exportCSV(){if(project)download(new Blob([getLanguage()==='ko'?'\ufeff':'',csvText(snapshot(),t)],{type:'text/csv'}),filename()+'-materials.csv')}
$('csvBtn').onclick=exportCSV;$('copyMaterials').onclick=safe(async()=>{if(!project)return;const text=[...countsFor(project.cells)].sort((a,b)=>b[1]-a[1]).map(([i,n])=>`${t(project.palette[i].name)}: ${n} (${t(`${Math.floor(n/64)} stacks + ${n%64}`)})`).join('\n');if(navigator.clipboard)await navigator.clipboard.writeText(text);else{const field=document.createElement('textarea');field.value=text;document.body.append(field);field.select();const ok=document.execCommand('copy');field.remove();if(!ok)throw Error('Clipboard unavailable. Download CSV instead.')}toast('Materials copied.')});
function pngBlueprint(){const p=snapshot(),s=p.width*p.height>16384?16:24,used=[...countsFor(p.cells)],c=document.createElement('canvas');c.width=Math.max(p.width*s+64,900);c.height=p.height*s+170+Math.ceil(used.length/3)*34;const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#152131';ctx.font='bold 22px sans-serif';ctx.fillText(p.name,32,32);ctx.font='12px sans-serif';ctx.fillText(t(`${p.width} × ${p.height} · Stand south, look north · X → Y ↑ · Bottom-left (0,0,0)`),32,57);ctx.drawImage(colorCanvas(p,s,true),32,80);ctx.strokeStyle='#0005';ctx.lineWidth=.5;ctx.beginPath();for(let x=0;x<=p.width;x++){ctx.moveTo(32+x*s,80);ctx.lineTo(32+x*s,80+p.height*s)}for(let y=0;y<=p.height;y++){ctx.moveTo(32,80+y*s);ctx.lineTo(32+p.width*s,80+y*s)}ctx.stroke();ctx.textAlign='center';ctx.font='9px monospace';p.cells.forEach((b,i)=>{if(b<0)return;const x=32+i%p.width*s+s/2,y=80+Math.floor(i/p.width)*s+s/2;ctx.fillStyle='#000a';ctx.fillRect(x-8,y-5,16,11);ctx.fillStyle='white';ctx.fillText(b+1,x,y+3)});ctx.textAlign='left';used.forEach(([idx,n],k)=>{const b=p.palette[idx],x=32+k%3*((c.width-64)/3),y=120+p.height*s+Math.floor(k/3)*34,t=textures.get(b.texture);if(t)ctx.drawImage(t,x,y-15,22,22);ctx.fillStyle='#152131';ctx.font='11px sans-serif';ctx.fillText(`${idx+1}. ${t(b.name)} · ${n}`,x+29,y)});c.toBlob(b=>b?download(b,filename()+'-blueprint.png'):toast('PNG export too large for this browser. Try smaller dimensions.'))}
function printMaterials(){const win=window.open('','_blank');if(!win)return toast('Allow popups to open the printable list.');win.document.write(`<!doctype html><title>${esc(project.name)} materials</title><style>body{font:14px Arial;padding:32px}table{border-collapse:collapse;width:100%}td,th{padding:9px;border-bottom:1px solid #ddd;text-align:left}@media print{button{display:none}}</style><h1 data-no-i18n>${esc(project.name)}</h1><p>${project.width} × ${project.height} · Java 1.20.4 · Stand south, look north</p><button onclick="print()">Print / Save as PDF</button><table><tr><th>Collected</th><th>Material</th><th>Count</th><th>Stacks + extra</th></tr>${[...countsFor(project.cells)].sort((a,b)=>b[1]-a[1]).map(([i,n])=>`<tr><td>□</td><td>${esc(project.palette[i].name)} ${esc(stateText(project.palette[i]))}</td><td>${n}</td><td>${Math.floor(n/64)} + ${n%64}</td></tr>`).join('')}</table>`);win.document.close();translateDocument(win.document.body);win.document.documentElement.lang=getLanguage()}
$('exportBtn').onclick=()=>{if(!project)return toast('Generate a build first.');modal('Export build',`<p>Exports use the current blueprint, including manual edits.</p><div class="export-grid"><button class="export-card" id="exportLitematic"><strong>◇ Litematica blueprint</strong><small>.litematic · native v6 · Java 1.20.4</small></button><button class="export-card" id="exportSchem"><strong>◇ WorldEdit schematic</strong><small>.schem · Sponge v2 · Java 1.20.4</small></button><button class="export-card" id="exportProject"><strong>▣ Project backup</strong><small>.blockloom · image, settings, edits & progress</small></button><button class="export-card" id="exportPng"><strong>▦ Blueprint + legend</strong><small>.png · numbered block grid</small></button><button class="export-card" id="exportCsv"><strong>▥ Materials spreadsheet</strong><small>.csv · counts, stacks & shulker quantities</small></button><button class="export-card" id="exportPrint"><strong>▤ Printable materials</strong><small>Print or save as PDF</small></button></div><p class="hint">One-block-deep vertical wall at Z=0. Origin is bottom-left. Both Minecraft formats are independently file-tested, but actual in-game import has not been tested here.</p>`);$('exportLitematic').onclick=safe(async()=>{download(await litematicBlob(snapshot()),filename()+'.litematic');toast('Litematica file exported.')});$('exportSchem').onclick=safe(async()=>{download(await schematicBlob(snapshot()),filename()+'.schem');toast('Schematic exported.')});$('exportProject').onclick=()=>download(new Blob([JSON.stringify(snapshot())],{type:'application/json'}),filename()+'.blockloom');$('exportPng').onclick=pngBlueprint;$('exportCsv').onclick=exportCSV;$('exportPrint').onclick=printMaterials};
$('saveBtn').onclick=safe(()=>persist(true));$('projectName').onchange=()=>{if(project){project.name=$('projectName').value;autosave()}};
async function openProject(p){p=validateProject(p,blocks);if(worker)worker.terminate();job++;$('loading').hidden=true;$('convertBtn').disabled=false;clearTimeout(saveTimer);project=p;done=new Set(p.done);collected=new Set(p.collected);sourceURL=p.source||sampleImage();source=await loadImage(sourceURL);$('projectName').value=p.name;$('sourceName').removeAttribute('data-no-i18n');$('sourceName').textContent='Saved source image';for(const id of ids){const el=$(id),v=p.settings[id];if(v!==undefined){if(el.type==='checkbox')el.checked=!!v;else el.value=v}}$('width').value=p.width;$('height').value=p.height;custom=new Set(Array.isArray(p.settings.custom)?p.settings.custom:[]);history=[];future=[];row=0;dirty=false;updatePalette();updateOutputs();document.querySelectorAll('[data-width]').forEach(b=>b.classList.toggle('selected',+b.dataset.width===p.width));refresh(true);$('modal').close();$('settingsStatus').textContent='Project restored · progress saved'}
async function showProjects(){if(db&&project)await persist();const all=db?await dbRun('readonly',s=>s.getAll()):[];all.sort((a,b)=>(b.updated||0)-(a.updated||0));modal('Your projects',`<p>Saved in this browser. Clearing site data removes these projects. Download backups to keep them safe.</p><div class="dialog-actions"><button id="importProjectBtn">Import project backup</button></div><div id="projectList">${all.map(p=>`<div class="project-card"><img src="${p.thumbnail||''}" alt=""><div class="project-info"><strong data-no-i18n>${esc(p.name)}</strong><p>${p.width} × ${p.height} · ${new Date(p.updated).toLocaleDateString()}</p></div><button data-open="${esc(p.id)}">Open</button><button data-duplicate="${esc(p.id)}">Duplicate</button><button data-delete="${esc(p.id)}" aria-label="Delete ${esc(p.name)}">✕</button></div>`).join('')||'<p>No saved projects yet.</p>'}</div>`);$('importProjectBtn').onclick=()=>$('projectInput').click();$('projectList').onclick=safe(async e=>{const id=e.target.dataset.open||e.target.dataset.duplicate||e.target.dataset.delete;if(!id)return;const p=all.find(p=>p.id===id);if(e.target.dataset.open)await openProject(p);else if(e.target.dataset.duplicate){await dbRun('readwrite',s=>s.put({...p,id:uuid(),name:p.name+' copy',updated:Date.now()}));await showProjects()}else{modal('Delete this saved project?',`<p>Delete “${esc(p.name)}” from this browser? Download a backup first to keep it.</p><div class="dialog-actions"><button id="cancelDelete">Cancel</button><button class="primary" id="confirmDelete">Delete project</button></div>`);$('cancelDelete').onclick=safe(showProjects);$('confirmDelete').onclick=safe(async()=>{await dbRun('readwrite',s=>s.delete(id));if(project?.id===id){project.id=uuid();$('modal').close();toast('Saved copy deleted. The open build is still available.')}else await showProjects()})}})}
$('projectsBtn').onclick=safe(showProjects);$('projectInput').onchange=safe(async e=>{const f=e.target.files[0];if(!f)return;if(f.size>20*1024*1024)throw Error('Project files must be smaller than 20 MB.');const p=validateProject(JSON.parse(await f.text()),blocks);p.id=uuid();await openProject(p);if(db)await persist();toast('Project imported.');e.target.value=''});
$('helpBtn').onclick=()=>modal('How to use the converter',`<div class="help-content"><h3>1. Choose your image and blocks</h3><p>Upload a picture, set its dimensions and palette, then Generate. Changes to conversion settings require another Generate; regenerating resets manual edits and progress. Duplicate a project first to preserve it.</p><h3>2. Inspect and edit</h3><p>Rotate and zoom the live 3D wall, or select Free camera: WASD moves, Q/E moves down/up, drag looks around, Shift moves faster and Escape exits. Use Blueprint & editor to paint, erase, pick blocks or replace every instance of a material. Undo and redo use Ctrl/Cmd+Z and Ctrl/Cmd+Shift+Z.</p><h3>3. Build from the bottom</h3><p>Stand south of the wall and look north. Bottom-left is (0,0,0), X increases right, Y increases up. Row 1 means Y=0. Air means leave a gap. Block-state notes specify glazed facing and deepslate axis. Mark cells or rows as placed.</p><h3>4. Keep a backup</h3><p>Projects autosave locally. Rename in the title field. Projects lets you reopen, duplicate, import or delete. Download a .blockloom backup before clearing site data or changing devices. Storage is separate for each site address.</p><h3>Versions and rendering</h3><p>The 162-block palette targets Java 1.20.4. Front textures are actual game assets. Side/top textures repeat the front face and may differ in-game. Lighting, emissions and resource packs are not simulated. A CPU 3D renderer works when WebGL is unavailable; its orbit view uses flat colors on exposed sides.</p><h3>Current limits</h3><p>This is one-block-thick pixel art, not an inferred statue or map art. Maximum size is 256 × 256. Stored source images are reduced to at most 1600 pixels. Survival-friendly and reduced-material palettes are convenience heuristics. Schematic and native Litematica files pass independent format checks; actual in-game imports remain unverified.</p><p>Not an official Minecraft product. Not approved by or associated with Mojang or Microsoft. Minecraft textures belong to Mojang/Microsoft.</p></div>`);
async function init(){blocks=await (await fetch('./blocks.json')).json();$('paintBlock').innerHTML=blocks.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('');await Promise.all(blocks.map(async b=>{try{textures.set(b.texture,await loadImage(b.texture))}catch{}}));try{await initDB()}catch{toast('Browser storage unavailable. Export backups to keep your work.')}updatePalette();const saved=db?await dbRun('readonly',s=>s.getAll()):[];if(saved.length){saved.sort((a,b)=>(b.updated||0)-(a.updated||0));await openProject(saved[0])}else await demo()}
initializeLanguage();
init().catch(e=>{console.error(e);toast('Unable to start: '+e.message);$('settingsStatus').textContent='Reload the page to try again.'});
function renderChest(entries){const slots=stackSlots(entries),pages=Math.max(1,Math.ceil(slots.length/54));chestPage=Math.max(0,Math.min(pages-1,chestPage));const start=chestPage*54;$('chestTitle').textContent='Large Chest';$('chestSummary').textContent=`${slots.length.toLocaleString()} stacks · ${pages} chest${pages===1?'':'s'}`;$('chestPage').textContent=`Chest ${chestPage+1} of ${pages}`;$('prevChest').disabled=chestPage===0;$('nextChest').disabled=chestPage===pages-1;$('chestGrid').innerHTML=Array.from({length:54},(_,j)=>{const slot=slots[start+j];if(!slot)return '<div class="chest-slot empty" aria-hidden="true"></div>';const b=project.palette[slot.block];return `<button class="chest-slot ${collected.has(b.id)?'collected':''}" data-material="${slot.block}" title="${esc(b.name)} × ${slot.count}" aria-label="${esc(b.name)}, ${slot.count} blocks${collected.has(b.id)?', collected':''}">${blockIcon(b)}<span>${slot.count}</span>${collected.has(b.id)?'<i>✓</i>':''}</button>`}).join('');$('materialsTable').hidden=$('materialView').value==='chest';$('chestPanel').hidden=$('materialView').value!=='chest';if(chestSelected!==null)showChestSelection(chestSelected)}
function showChestSelection(i){if(!project.palette[i])return;chestSelected=i;const b=project.palette[i],count=countsFor(project.cells).get(i)||0;$('chestSelection').innerHTML=`<img src="${b.texture}" alt=""><div><strong>${esc(b.name)}</strong><p>${count.toLocaleString()} total · ${Math.floor(count/64)} full stacks + ${count%64}</p></div><button id="collectChest">${collected.has(b.id)?'Unmark collected':'Mark material collected'}</button>`;$('collectChest').onclick=()=>{collected.has(b.id)?collected.delete(b.id):collected.add(b.id);renderMaterials();autosave()}}
$('chestGrid').onclick=e=>{const b=e.target.closest('[data-material]');if(b)showChestSelection(+b.dataset.material)};$('materialView').onchange=()=>project&&renderMaterials();$('prevChest').onclick=()=>{chestPage--;renderMaterials()};$('nextChest').onclick=()=>{chestPage++;renderMaterials()};

// Isometric inventory blocks retain crisp, actual block textures on three faces.
function blockIcon(b){const texture=esc(b.texture);return `<svg class="inventory-block" viewBox="0 0 64 72" aria-hidden="true" xmlns="http://www.w3.org/2000/svg"><path d="M32 4 60 20 60 52 32 68 4 52 4 20Z" fill="rgb(${b.color.join(',')})"/><image href="${texture}" width="16" height="16" transform="matrix(1.75 1 -1.75 1 32 4)"/><image href="${texture}" width="16" height="16" transform="matrix(1.75 1 0 2 4 20)"/><path d="M4 20 32 36 32 68 4 52Z" fill="#000" opacity=".12"/><image href="${texture}" width="16" height="16" transform="matrix(1.75 -1 0 2 32 36)"/><path d="M32 36 60 20 60 52 32 68Z" fill="#000" opacity=".26"/></svg>`}

let textureZoom=1,texturePan=[0,0],textureDrag=null;
function applyTextureView(){ $('previewCanvas').style.transform=`translate(${texturePan[0]}px,${texturePan[1]}px) scale(${textureZoom})`; }
function resetTextureView(){textureZoom=1;texturePan=[0,0];applyTextureView()}
$('canvasHost').addEventListener('wheel',e=>{if(view==='3d')return;e.preventDefault();const old=textureZoom;textureZoom=Math.max(.25,Math.min(24,old*Math.exp(-e.deltaY*.0015)));const r=$('canvasHost').getBoundingClientRect(),x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2;texturePan=[x-(x-texturePan[0])*textureZoom/old,y-(y-texturePan[1])*textureZoom/old];applyTextureView()},{passive:false});
$('canvasHost').addEventListener('pointerdown',e=>{textureDrag=[e.clientX,e.clientY];$('canvasHost').setPointerCapture(e.pointerId)});
$('canvasHost').addEventListener('pointermove',e=>{if(!textureDrag)return;texturePan[0]+=e.clientX-textureDrag[0];texturePan[1]+=e.clientY-textureDrag[1];textureDrag=[e.clientX,e.clientY];applyTextureView()});
for(const name of ['pointerup','pointercancel'])$('canvasHost').addEventListener(name,()=>textureDrag=null);

function fitBlueprint(){if(!project)return;const host=$('blueprintScroll');const max=Math.min(40,Math.floor(4096/Math.max(project.width,project.height)));$('zoom').value=Math.max(1,Math.min(max,Math.floor(Math.min((host.clientWidth-32)/project.width,(host.clientHeight-32)/project.height))));renderBlueprint();host.scrollTop=0;host.scrollLeft=0}
$('fitBlueprint').onclick=fitBlueprint;
$('rowCanvas').onclick=e=>{const r=e.currentTarget.getBoundingClientRect();row=project.height-1-Math.floor((e.clientY-r.top)/r.height*project.height);renderGuide()};
